<?php $__env->startSection('title','Employee'); ?><?php $__env->startSection('content'); ?><form class="card grid gap-3 md:grid-cols-2" method="post" action="<?php echo e($employee->exists?route('employees.update',$employee):route('employees.store')); ?>"><?php echo csrf_field(); ?> <?php if($employee->exists): ?><?php echo method_field('put'); ?><?php endif; ?><input class="input" name="name" placeholder="Name" value="<?php echo e(old('name',$employee->name)); ?>"><input class="input" name="iqama_no" placeholder="Iqama" value="<?php echo e(old('iqama_no',$employee->iqama_no)); ?>"><select class="input" name="current_project_id"><option value="">Project</option><?php $__currentLoopData = $projects; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $p): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($p->id); ?>" <?php if($employee->current_project_id==$p->id): echo 'selected'; endif; ?>><?php echo e($p->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><select class="input" name="designation_id"><option value="">Designation</option><?php $__currentLoopData = $designations; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $d): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($d->id); ?>" <?php if($employee->designation_id==$d->id): echo 'selected'; endif; ?>><?php echo e($d->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><select class="input" name="company_id"><option value="">Company</option><?php $__currentLoopData = $companies; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $c): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($c->id); ?>" <?php if($employee->company_id==$c->id): echo 'selected'; endif; ?>><?php echo e($c->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><input class="input" name="hourly_rate" placeholder="Hourly rate" value="<?php echo e($employee->hourly_rate); ?>"><input class="input" name="monthly_salary" placeholder="Monthly salary" value="<?php echo e($employee->monthly_salary); ?>"><input type="hidden" name="status" value="active"><button class="btn-primary">Save</button></form><?php $__env->stopSection(); ?>

